let db;try{db=JSON.parse(localStorage.getItem('nido-demo-v3'))}catch{}if(!db||db.version!==3)db=seed();
let user=localStorage.getItem('nido-actor-v3')||'sofia';if(!actors.includes(user))user='sofia';let tab='calendar',filter='all',selected=today(),calMode='week',calSection='agenda',docQuery='',sheetState=null,chat=[];
function canOwner(owner,category='clinical'){if(user===owner)return true;const g=db.grants[owner]?.[user];return g==='manage'||(g==='care'&&category==='care')}
function can(record,category='clinical'){if(!record)return false;if(record.owner===user)return true;if(record.visibility==='private')return false;if(!canOwner(record.owner,record.scope||category))return false;if(record.medSource&&!can(db.meds.find(m=>m.id===record.medSource)))return false;if(record.source){const source=db.documents.find(d=>d.id===record.source);if(!can(source))return false}return true}
const visible=(list,category)=>list.filter(r=>can(r,category));
const allowedPatients=(category='clinical')=>patientIds.filter(p=>canOwner(p,category));
const personStyle=p=>`--color:${people[p].color};--tint:${people[p].tint}`;
const avatar=p=>`<span class="avatar" style="${personStyle(p)}">${people[p].initial}</span>`;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3200)}
function persist(){try{localStorage.setItem('nido-demo-v3',JSON.stringify(db));return true}catch{toast('No hay espacio para guardar. Probá con un archivo más pequeño.');return false}}
function button(text,action,arg='',cls='btn'){const labels={alerts:'Ver avisos',close:'Cerrar',switch:'Cambiar perfil',upload:'Agregar documento','new-event':'Agregar actividad','new-med':'Agregar medicamento',shift:arg==='-1'?'Período anterior':'Período siguiente'};return `<button ${labels[action]?`aria-label="${labels[action]}"`:''} class="${cls}" data-action="${action}" data-id="${esc(arg)}">${text}</button>`}
function scopeChip(r){return r.visibility==='private'?'<span class="tag private">Solo yo</span>':'<span class="tag">Compartido según permisos</span>'}
function empty(title,text,action='',label='Agregar'){return `<div class="empty"><h3>${title}</h3><p>${text}</p>${action?button(label,action):''}</div>`}
function filtered(list,cat){return visible(list,cat).filter(r=>filter==='all'||r.owner===filter)}
function chips(category='clinical'){const ids=allowedPatients(category);return `<div class="chips">${button('Todos','filter','all',`chip ${filter==='all'?'active':''}`)}${ids.map(p=>button(`<i class="dot" style="${personStyle(p)}"></i>${people[p].name}`,'filter',p,`chip ${filter===p?'active':''}`)).join('')}</div>`}
function render(){const title={calendar:'Calendario',docs:'Documentos',chat:'Asistente',meds:'Medicamentos',family:'Familia'};$('#app').innerHTML=`<div class="app"><header><div><div class="brand">nido<span style="color:#c19b66">.</span></div><div class="eyebrow">Tu familia, cerca</div></div><div class="row" style="gap:7px">${button(icon('bell'),'alerts','','iconbtn')}${button(`${avatar(user)}<span class="name">${people[user].name} ⌄</span>`,'switch','','identity')}</div></header><div class="switcher-banner">Demo · datos ficticios · Cambiá de perfil para explorar</div><main class="main" id="main">${({calendar:calendarPage,docs:docsPage,chat:chatPage,meds:medsPage,family:familyPage})[tab]()}</main><nav class="nav" aria-label="Navegación principal">${Object.keys(title).map(k=>button(icon(k)+`<span>${title[k]}</span>`,'tab',k,tab===k?'active':'')).join('')}</nav></div>`;if(sheetState)renderSheet()}
function eventCard(e){const done=e.status==='done';return `<button class="card action event" style="${personStyle(e.owner)}" data-action="event" data-id="${e.id}"><div class="between"><div class="time">${e.time||dateLabel(e.date)} · ${esc(e.type)}</div>${icon('next')}</div><h3>${esc(e.title)}</h3><p>${people[e.owner].name} · ${people[e.assignee]?.name||'Sin responsable'}</p><div class="meta"><span class="tag ${done?'done':e.date&&e.date<today()?'warn':''}">${done?'Completado':e.date&&e.date<today()?'Pendiente de confirmar':'Por realizar'}</span>${e.visibility==='private'?scopeChip(e):''}</div></button>`}
function calendarPage(){let d=new Date(selected+'T12:00'),days=[];if(calMode==='week'){let start=addDay(selected,-((d.getDay()+6)%7));days=Array.from({length:7},(_,i)=>addDay(start,i))}else{let start=selected.slice(0,8)+'01',count=new Date(d.getFullYear(),d.getMonth()+1,0).getDate(),padding=(new Date(start+'T12:00').getDay()+6)%7;days=[...Array(padding).fill(null),...Array.from({length:count},(_,i)=>addDay(start,i))]}
const ev=filtered(db.events,'care').filter(e=>e.status!=='canceled');const agenda=ev.filter(e=>e.date===selected).sort((a,b)=>a.time.localeCompare(b.time));const tasks=ev.filter(e=>e.status==='pending').sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'));
return `<div class="page-title between"><div><h1>Calendario</h1><p>${user==='sofia'?'Cada persona, su próximo paso.':'Lo que importa para tu día.'}</p></div>${button(icon('plus'),'new-event','','iconbtn')}</div>${chips('care')}<div class="seg">${button('Agenda','cal-section','agenda',calSection==='agenda'?'active':'')}${button(`Pendientes · ${tasks.length}`,'cal-section','tasks',calSection==='tasks'?'active':'')}</div>${calSection==='agenda'?`<div class="between"><h2 style="font-size:22px">${esc(d.toLocaleDateString('es-UY',{month:'long',year:'numeric'}))}</h2><div class="row" style="gap:2px">${button(icon('back'),'shift','-1','iconbtn')}${button(icon('next'),'shift','1','iconbtn')}</div></div><div class="between">${button('Hoy','today','','home-link')}${button(calMode==='week'?'Ver mes':'Ver semana','cal-mode','','home-link')}</div><div class="${calMode==='week'?'week':'month'}">${days.map(iso=>iso?button(`<small>${new Date(iso+'T12:00').toLocaleDateString('es-UY',{weekday:'short'}).slice(0,2)}</small><span>${+iso.slice(-2)}</span><span class="marker" style="visibility:${ev.some(e=>e.date===iso)?'visible':'hidden'}"></span>`,'day',iso,`day ${selected===iso?'active':''} ${iso===today()?'today':''}`):'<span></span>').join('')}</div><div class="section-title"><span>${dateLabel(selected)}</span><span>${agenda.length} actividades</span></div>${agenda.length?agenda.map(eventCard).join(''):empty('Un día con espacio','No hay actividades registradas para esta fecha.','new-event','Agregar actividad')}`:`<div class="section-title">Próximos pasos</div>${tasks.length?tasks.map(eventCard).join(''):empty('Todo al día','No tenés pendientes visibles en este momento.')}<div class="section-title">Realizados</div>${ev.filter(e=>e.status==='done').map(eventCard).join('')||'<p class="muted tiny">Acá quedará el registro de las actividades completadas.</p>'}`}`}
function docCard(d){return `<button class="card action" data-action="document" data-id="${d.id}"><div class="row"><span class="avatar" style="${personStyle(d.owner)}">${icon('docs')}</span><div class="grow"><h3>${esc(d.title)}</h3><p>${people[d.owner].name} · ${dateLabel(d.date)}</p></div>${icon('next')}</div><div class="meta"><span class="tag">${esc(d.kind)}</span>${scopeChip(d)}</div></button>`}
function docsPage(){const docs=filtered(db.documents).filter(d=>(d.title+' '+d.text).toLowerCase().includes(docQuery.toLowerCase()));return `<div class="page-title between"><div><h1>Documentos</h1><p>Todo a mano, cuando lo necesitás.</p></div>${allowedPatients().length?button(icon('plus'),'upload','','iconbtn'):''}</div>${chips()}<form id="search-form" class="search">${icon('search')}<input name="query" aria-label="Buscar documentos" placeholder="Buscar un documento…" value="${esc(docQuery)}" type="search"></form>${docs.length?docs.map(docCard).join(''):empty('Sin documentos','No hay documentos disponibles para esta búsqueda.')}`}
const qty=m=>m.batches.reduce((s,b)=>s+b.qty,0);
const daysTo=d=>d?Math.round((new Date(d+'T12:00')-new Date(today()+'T12:00'))/86400000):null;
function medsPage(){const meds=filtered(db.meds);return `<div class="page-title between"><div><h1>Medicamentos</h1><p>Existencias, recetas y reposición.</p></div>${allowedPatients().length?button(icon('plus'),'new-med','','iconbtn'):''}</div>${chips()}${meds.some(m=>m.shopping)?`<div class="summary"><h3>${meds.filter(m=>m.shopping).length} en la lista de reposición</h3><p>Las compras se coordinan fuera de Nido.</p></div>`:''}${meds.map(m=>`<button class="card action" data-action="med" data-id="${m.id}"><div class="between"><div><small>${people[m.owner].name}</small><h3 style="margin-top:5px">${esc(m.title)}</h3></div><span class="avatar" style="${personStyle(m.owner)}">${icon('meds')}</span></div><div class="between" style="margin-top:18px"><div><span class="quantity">${qty(m)}</span> <small>${esc(m.unit)}</small></div><span class="tag ${qty(m)<=7?'warn':''}">${qty(m)<=7?'Revisar stock':'Cantidad registrada'}</span></div><div class="meta">${m.shopping?'<span class="tag warn">En lista de reposición</span>':''}${m.rx?`<span class="tag ${daysTo(m.rx)<=15?'warn':''}">Receta · ${dateLabel(m.rx)}</span>`:''}</div></button>`).join('')||empty('Sin medicamentos','Todavía no hay medicamentos compartidos con este perfil.')}`}
function familyPage(){let ids=allowedPatients('care');return `<div class="page-title"><h1>${user==='sofia'?'Mi familia':'Mi espacio'}</h1><p>Personas, cuidados y privacidad.</p></div><div class="card"><div class="row">${avatar(user)}<div><h3>${people[user].full}</h3><p>${people[user].role}</p></div></div>${button('Cambiar de perfil de prueba','switch','','btn quiet full')}<small>El cambio de perfil simula usuarios; no es un inicio de sesión real.</small></div><div class="section-title">Información disponible</div>${ids.map(p=>button(`<div class="row">${avatar(p)}<div class="grow"><h3>${people[p].name}</h3><p>${people[p].role}</p></div>${icon('next')}</div>`,'person',p,'card action')).join('')}${user==='sofia'&&!canOwner('antonio','care')?`<div class="card"><h3>Antonio</h3><p>Necesitás su autorización para acceder a su información.</p>${button(db.requests.some(r=>r.owner==='antonio'&&r.status==='pending')?'Solicitud pendiente':'Solicitar acceso','request','antonio','btn quiet full')}</div>`:''}${user==='antonio'?button('Quién puede ver mi información','permissions','antonio','btn secondary full'):''}<div class="notice demo">Esta familia y todos sus registros son ficticios. El prototipo guarda cambios solo en este navegador.</div>${button('Restablecer datos de ejemplo','reset','','muted-button')}`}
function chatPage(){return `<div class="page-title"><h1>Tu asistente</h1><p>Encontrá información y organizá el próximo paso.</p></div><div class="bubble">Hola, ${people[user].name}. Puedo buscar entre los documentos y las actividades disponibles para tu perfil. ¿Qué necesitás encontrar?</div><div class="chips">${button('Próximos turnos','ask','turnos','chip')}${button('Mis documentos','ask','documentos','chip')}${button('Reposición','ask','medicamentos','chip')}${button('Crear pendiente','new-event','','chip')}</div>${chat.map(m=>`<div class="bubble ${m.role==='user'?'user':''}">${m.html||esc(m.text)}</div>`).join('')}<form id="chat-form" class="chat-form"><input name="query" aria-label="Mensaje al asistente" placeholder="Buscá una consulta o documento" required autocomplete="off"><button class="btn" aria-label="Enviar mensaje">${icon('next')}</button></form><div class="notice demo">Demostración de búsqueda, sin IA conectada. No interpreta resultados ni recomienda tratamientos.</div>`}
function ask(q){chat.push({role:'user',text:q});const term=q.toLocaleLowerCase();let results='';if(/grave|diagn[oó]st|tratamiento|qu[eé] significa/.test(term))results='Puedo recuperar la fuente y ayudarte a guardar una pregunta para tu consulta. La interpretación de resultados corresponde al profesional tratante.';else if(/turno|consulta|agenda/.test(term)){let es=visible(db.events,'care').filter(e=>e.status==='pending');results=es.map(e=>button(`${esc(e.title)} · ${dateLabel(e.date)}`,'event',e.id,'attachment')).join('')}else if(/medic|stock|reposici/.test(term)){results=visible(db.meds).map(m=>button(`${esc(m.title)} · ${qty(m)} ${esc(m.unit)}`,'med',m.id,'attachment')).join('')}else{const docs=visible(db.documents).filter(d=>/documentos|informes/.test(term)||(d.title+' '+d.text).toLowerCase().includes(term));results=docs.map(d=>button(`${esc(d.title)} · ${people[d.owner].name}`,'document',d.id,'attachment')).join('')}
chat.push({role:'ai',html:results||'No encontré resultados en la información disponible para tu perfil. Probá con otro término.'});render();$('#main').scrollTop=$('#main').scrollHeight}
function open(type,id='',data={}){sheetState={type,id,...data};renderSheet()}
function close(){sheetState=null;$('#modal').innerHTML='';$('#app').removeAttribute('inert')}
function sheet(title,body){$('#app').setAttribute('inert','');$('#modal').innerHTML=`<div class="sheet-backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="handle"></div><div class="sheet-head"><h2>${title}</h2>${button(icon('close'),'close','','iconbtn')}</div>${body}</section></div>`}
function patientOptions(category='clinical',sel){return allowedPatients(category).map(p=>`<option value="${p}" ${sel===p?'selected':''}>${people[p].name}</option>`).join('')}
function privateField(record){return record?.owner===user?`<label class="check"><input type="checkbox" name="private" ${record.visibility==='private'?'checked':''}>Solo yo: no compartir este registro</label>`:''}
function history(list){return `<div class="section-title">Historial</div>${list?.length?`<div class="history">${list.map(h=>`<p>${esc(h.action)} · ${people[h.by]?.name||'Usuario'}<br>${esc(h.at)}</p>`).join('')}</div>`:'<p class="muted tiny">Todavía no hay cambios registrados.</p>'}`}
function log(record,action){record.history??=[];record.history.push({by:user,at:stamp(),action});persist()}
function renderSheet(){let s=sheetState;if(!s)return;let r;
if(s.type==='switch')return sheet('Elegí un perfil',`<p class="muted tiny">Explorá cómo cambia Nido para cada persona.</p>${actors.map(p=>button(`${avatar(p)}<span class="grow"><strong>${people[p].name}</strong><small>${people[p].role} · ${people[p].detail}</small></span>${user===p?icon('check'):icon('next')}`,'actor',p,`person-choice ${user===p?'selected':''}`)).join('')}<div class="notice demo">Personajes ficticios. Los permisos se simulan en este navegador; no cargues información médica real.</div>`);
if(s.type==='event'){r=db.events.find(e=>e.id===s.id);if(!can(r,'care'))return denied();return sheet('Detalle de actividad',`<div class="meta">${scopeChip(r)}<span class="tag">${esc(r.type)}</span></div><h2 style="margin-top:18px">${esc(r.title)}</h2><dl class="details"><dt>Para</dt><dd>${people[r.owner].full}</dd><dt>Cuándo</dt><dd>${dateLabel(r.date)} ${esc(r.time)}</dd><dt>Responsable</dt><dd>${people[r.assignee]?.name||'Sin asignar'}</dd><dt>Lugar</dt><dd>${esc(r.location)||'Por confirmar'}</dd><dt>Aviso</dt><dd>${esc(r.reminder||'Sin recordatorio')}</dd><dt>Se avisaría a</dt><dd>${people[r.recipient||r.assignee]?.name||'Sin destinatario'}</dd></dl><p>${esc(r.notes||'Sin notas adicionales.')}</p>${r.source?button(icon('docs')+' Ver documento de origen','document',r.source,'btn secondary full'):''}<div class="actions">${r.status!=='done'?button('Marcar realizada','complete',r.id):button('Reabrir pendiente','reopen',r.id)}${button('Editar','edit-event',r.id,'btn quiet')}</div>${button('Agregar pregunta para la consulta','question',r.id,'btn quiet full')}${(r.questions||[]).map(q=>`<div class="notice">${esc(q)}</div>`).join('')}${button('Cancelar actividad','confirm-cancel',r.id,'muted-button')}${history(r.history)}<div class="notice demo">El aviso se configura para la demo; no envía notificaciones. Agendar no reserva un turno en el prestador.</div>`)}
if(s.type==='event-form'){r=s.id?db.events.find(e=>e.id===s.id):null;if(r&&!can(r,'care'))return denied();return sheet(r?'Editar actividad':'Nueva actividad',`<form id="event-form"><label>Integrante</label><select name="owner">${patientOptions('care',r?.owner||s.owner|| (filter!=='all'?filter:allowedPatients('care')[0]))}</select><label>Qué hay que hacer</label><input name="title" value="${esc(r?.title||'')}" placeholder="Ej. coordinar control pediátrico" required><div class="inline"><div><label>Fecha (opcional)</label><input type="date" name="date" value="${r?.date??selected}"></div><div><label>Hora (opcional)</label><input type="time" name="time" value="${r?.time||''}"></div></div><label>Tipo</label><select name="type">${['Consulta','Estudio','Trámite','Pendiente','Cuidado','Medicación'].map(t=>`<option ${r?.type===t?'selected':''}>${t}</option>`).join('')}</select><label>Responsable</label><select name="assignee">${actors.filter(p=>p===user||user==='sofia').map(p=>`<option value="${p}" ${r?.assignee===p?'selected':''}>${people[p].name}</option>`).join('')}</select><label>Lugar</label><input name="location" value="${esc(r?.location||'')}" placeholder="Prestador, dirección o por confirmar"><label>Recordatorio</label><select name="reminder">${['Sin recordatorio','30 minutos antes','1 día antes','2 días antes','1 semana antes'].map(t=>`<option ${r?.reminder===t?'selected':''}>${t}</option>`).join('')}</select><label>Destinatario del aviso</label><select name="recipient">${actors.filter(p=>p===user||p===r?.owner||user==='sofia').map(p=>`<option value="${p}" ${r?.recipient===p?'selected':''}>${people[p].name}</option>`).join('')}</select><label>Notas y preparación</label><textarea name="notes">${esc(r?.notes||'')}</textarea>${privateField(r||{owner:user,visibility:'shared'})}<div class="actions"><button class="btn full">Guardar actividad</button></div></form>`)}
if(s.type==='document'){r=db.documents.find(d=>d.id===s.id);if(!can(r))return denied();return sheet('Documento',`<div class="meta">${scopeChip(r)}<span class="tag">${esc(r.kind)}</span></div><h2 style="margin:18px 0 7px">${esc(r.title)}</h2><p class="muted tiny">${people[r.owner].full} · ${dateLabel(r.date)}</p><div class="paper" style="margin-top:20px"><div class="eyebrow">Fuente guardada</div>${esc(r.text)}</div>${r.attachment?`<a class="attachment" href="${r.attachment}" download="${esc(r.filename||'documento')}">Descargar archivo adjunto</a>`:''}<div class="actions">${button('Crear pendiente','doc-task',r.id)}</div>${r.owner===user?button(icon('lock')+' Cambiar visibilidad','doc-privacy',r.id,'btn quiet full'):''}<div class="notice demo">Documento ficticio de demostración. Nido recupera la fuente; no interpreta el resultado.</div>`)}
if(s.type==='upload'){return sheet('Agregar documento',`<div class="progress"><span class="active"></span><span></span><span></span></div><p>Una foto o archivo, y lo importante queda a mano.</p><form id="upload-form"><label>¿De quién es?</label><select name="owner">${patientOptions('clinical',filter!=='all'?filter:user)}</select><label>Foto o PDF de prueba</label><input name="file" type="file" accept="image/*,application/pdf"><p class="muted tiny" style="margin-top:7px">Usá archivos ficticios. Máximo 1 MB para esta demo.</p><div class="actions"><button class="btn full">Continuar con mi archivo</button></div></form><div class="section-title">O explorá un ejemplo preparado</div>${button('Usar indicación de control','example','','btn secondary full')}`)}
if(s.type==='review'){return sheet('Revisar información',`<div class="progress"><span class="active"></span><span class="active"></span><span></span></div><div class="notice demo">${s.example?'Datos propuestos del ejemplo, simulados. Revisalos antes de guardar.':'Completá los datos de tu archivo. La extracción automática aún no está conectada.'}</div>${s.attachment?.startsWith('data:image/')?`<img class="file-preview" src="${s.attachment}" alt="Archivo seleccionado">`:''}<form id="review-form"><label>Integrante</label><select name="owner">${patientOptions('clinical',s.owner)}</select><label>Título</label><input name="title" value="${s.example?'Indicación para control de seguimiento':esc(s.filename||'')}" required><label>Fecha del documento</label><input name="date" type="date" value="${today()}"><label>Contenido o nota de la fuente</label><textarea name="text" required>${s.example?'EJEMPLO FICTICIO · Indicación de consulta\nSolicitar control de seguimiento dentro de un mes. Llevar los informes anteriores a la consulta.':''}</textarea><label class="check"><input name="private" type="checkbox">Guardar como privado para su titular</label><label class="check"><input name="confirmed" type="checkbox" required>Revisé la persona y los datos antes de guardarlos</label><button class="btn full" style="margin-top:18px">Confirmar y guardar</button></form>`)}
if(s.type==='doc-saved'){r=db.documents.find(d=>d.id===s.id);return sheet('Documento guardado',`<div class="progress"><span class="active"></span><span class="active"></span><span class="active"></span></div><div class="summary"><h3>La información ya tiene su lugar.</h3><p>Podés convertirla en un próximo paso con fecha y responsable.</p></div>${can(r)?button('Crear un pendiente','doc-task',r.id,'btn full'):''}${button('Terminar','finish-upload','','btn quiet full')}`)}
if(s.type==='doc-task'){r=db.documents.find(d=>d.id===s.id);if(!can(r))return denied();return sheet('Documento a pendiente',`<p class="muted tiny">Vinculado a ${esc(r.title)} · ${people[r.owner].name}</p><form id="doc-task-form"><label>Próximo paso</label><input name="title" placeholder="Ej. solicitar control de seguimiento" required><label>Cuándo (opcional)</label><input name="date" type="date"><label>Responsable</label><select name="assignee">${actors.filter(p=>p===user||user==='sofia').map(p=>`<option value="${p}">${people[p].name}</option>`).join('')}</select><button class="btn full" style="margin-top:18px">Crear pendiente</button></form><div class="notice">El pendiente conserva la privacidad del documento de origen.</div>`)}
if(s.type==='med'){r=db.meds.find(m=>m.id===s.id);if(!can(r))return denied();return sheet('Detalle de medicamento',`<small>${people[r.owner].name}</small><h2 style="margin:7px 0 18px">${esc(r.title)}</h2><span class="quantity">${qty(r)}</span> <small>${esc(r.unit)} registrados</small><p class="muted tiny">Última actualización: ${dateLabel(r.updated)}</p><div class="section-title">Cajas y vencimientos</div>${r.batches.map((b,i)=>`<div class="card between"><div><h3>Caja ${i+1} · ${b.qty} ${esc(r.unit)}</h3><p>Vence: ${dateLabel(b.expiry)}</p></div>${button('Corregir','batch',r.id+':'+b.id,'btn quiet tiny')}</div>`).join('')}<div class="notice">Cantidad registrada, no medida automáticamente. Vencimiento de receta: ${r.rx?dateLabel(r.rx):'Sin registrar'}.</div><div class="actions">${button(r.shopping?'Quitar de la lista':'Agregar a reposición','shopping',r.id,'btn secondary')}${button('Registrar compra','purchase',r.id,'btn')}</div>${button('Gestionar renovación de receta','renew',r.id,'btn quiet full')}${history(r.history)}`)}
if(s.type==='med-form')return sheet('Agregar medicamento',`<form id="med-form"><label>Integrante</label><select name="owner">${patientOptions('clinical',filter!=='all'?filter:user)}</select><label>Nombre tal como figura en el envase</label><input name="title" required placeholder="Nombre y presentación"><div class="inline"><div><label>Cantidad</label><input name="qty" type="number" min="0" step="1" required></div><div><label>Unidad</label><select name="unit"><option>comprimidos</option><option>cápsulas</option><option>frascos</option><option>unidades</option></select></div></div><label>Vencimiento de esta caja (opcional)</label><input name="expiry" type="date"><label>Vencimiento de receta (opcional)</label><input name="rx" type="date"><button class="btn full" style="margin-top:20px">Guardar medicamento</button></form>`);
if(s.type==='batch'||s.type==='purchase'){r=db.meds.find(m=>m.id===s.id);if(!can(r))return denied();let b=r.batches.find(b=>b.id===s.batch);return sheet(s.type==='purchase'?'Registrar compra':'Corregir existencias',`<p>${esc(r.title)} · ${people[r.owner].name}</p><form id="stock-form"><label>${s.type==='purchase'?'Cantidad de la nueva caja':'Cantidad restante de esta caja'}</label><input type="number" name="qty" min="0" step="1" value="${b?.qty??''}" required><label>Vencimiento del envase</label><input type="date" name="expiry" value="${b?.expiry||''}"><button class="btn full" style="margin-top:20px">Guardar cantidad</button></form><div class="notice demo">Este registro no envía un pedido a una farmacia.</div>`)}
if(s.type==='person'){const p=s.id;if(!canOwner(p,'care'))return denied();return sheet(people[p].full,`<div class="row">${avatar(p)}<div><h3>${people[p].role}</h3><p class="muted tiny">Información disponible para ${people[user].name}</p></div></div><div class="actions">${canOwner(p)?button('Ver documentos','person-docs',p,'btn secondary'):''}${button('Notas de cuidado','notes',p,'btn secondary')}</div>${canOwner(p)?button('Registro de vacunas','vaccines',p,'btn quiet full'):''}${user===p&&p==='antonio'?button(icon('lock')+' Acceso y permisos','permissions',p,'btn quiet full'):''}${user==='sofia'&&p==='antonio'?'<div class="notice">Antonio comparte su información cotidiana con vos. Cada titular conserva el control de sus documentos privados.</div>':''}`)}
if(s.type==='notes'){if(!canOwner(s.id,'care'))return denied();return sheet('Notas de cuidado',`<p class="muted tiny">${people[s.id].name}</p>${visible(db.notes,'care').filter(n=>n.owner===s.id).slice().reverse().map(n=>`<div class="card"><p style="color:inherit">${esc(n.text)}</p><small>${people[n.by].name} · ${dateLabel(n.date)}</small></div>`).join('')||empty('Sin notas','Podés registrar cómo fue el día.')}<form id="note-form"><label>Nueva observación</label><textarea name="text" placeholder="Qué pasó, cuándo y qué se hizo" required></textarea><button class="btn full" style="margin-top:15px">Guardar observación</button></form>`)}
if(s.type==='vaccines'){if(!canOwner(s.id))return denied();return sheet('Registro de vacunas',`<p class="muted tiny">${people[s.id].name}</p><div class="notice">Se muestran registros ingresados, no un calendario de recomendaciones. Revisá el carné con el prestador.</div>${visible(db.vaccines).filter(v=>v.owner===s.id).map(v=>`<div class="card"><h3>${esc(v.title)}</h3><p>${dateLabel(v.date)} · ${esc(v.text)}</p></div>`).join('')||empty('Sin registros','Agregá un registro de ejemplo del carné.')}<form id="vaccine-form"><label>Vacuna / dosis tal como figura en el carné</label><input name="title" required><label>Fecha registrada</label><input type="date" name="date" required><button class="btn full" style="margin-top:18px">Guardar registro</button></form>`)}
if(s.type==='permissions'){if(user!==s.id)return denied();const grants=db.grants[s.id];return sheet('Acceso y permisos',`<p>Vos decidís quién puede acompañarte y qué información compartís.</p><div class="notice">Los documentos marcados «Solo yo» quedan fuera de cualquier permiso general.</div>${Object.entries(grants).map(([who,scope])=>`<div class="card"><div class="row">${avatar(who)}<div><h3>${people[who].name}</h3><p>${scope==='manage'?'Información compartida y gestiones':'Solo tareas y notas de cuidado'}</p></div></div>${button('Revocar acceso','revoke',who,'btn quiet full')}</div>`).join('')||empty('Sin accesos activos','Tu información solo está disponible para vos.')}${['sofia','rosa'].filter(p=>!grants[p]).map(p=>button(`Compartir con ${people[p].name}`,'grant',p,'btn secondary full')).join('')}${db.requests.filter(r=>r.owner===user&&r.status==='pending').map(r=>`<div class="card"><h3>${people[r.by].name} solicita acceso</h3>${button('Aceptar solicitud','approve',r.id,'btn full')}</div>`).join('')}${history(db.audit.filter(a=>a.owner===user))}`)}
if(s.type==='privacy'){r=db.documents.find(d=>d.id===s.id);if(r?.owner!==user)return denied();return sheet('Visibilidad del documento',`<h3>${esc(r.title)}</h3><form id="privacy-form"><label>¿Quién puede verlo?</label><select name="visibility"><option value="private" ${r.visibility==='private'?'selected':''}>Solo yo</option><option value="shared" ${r.visibility==='shared'?'selected':''}>Personas con mi autorización general</option></select><div class="notice">Las actividades vinculadas respetan la privacidad del documento. Compartir no otorga acceso a personas sin autorización.</div><button class="btn full">Guardar visibilidad</button></form>`)}
if(s.type==='alerts'){const ev=visible(db.events,'care').filter(e=>e.status==='pending'&&e.date&&e.date<=addDay(today(),3));const meds=visible(db.meds).filter(m=>qty(m)<=7||m.rx&&daysTo(m.rx)<=15);return sheet('Avisos',`<p class="muted tiny">Resumen de próximas gestiones para tu perfil.</p>${ev.map(eventCard).join('')}${meds.map(m=>button(`<h3>${esc(m.title)}</h3><p>Revisar existencias o vigencia de receta · ${people[m.owner].name}</p>`,'med',m.id,'card action')).join('')}${!ev.length&&!meds.length?empty('Sin avisos','No hay gestiones próximas disponibles.'):''}<div class="notice demo">Vista de avisos de la demo. No se envían mensajes ni notificaciones reales.</div>`)}
if(s.type==='question'){r=db.events.find(e=>e.id===s.id);if(!can(r,'care'))return denied();return sheet('Pregunta para la consulta',`<form id="question-form"><label>¿Qué querés conversar con el profesional?</label><textarea name="text" required></textarea><button class="btn full" style="margin-top:15px">Guardar pregunta</button></form>`)}
if(s.type==='cancel'){r=db.events.find(e=>e.id===s.id);if(!can(r,'care'))return denied();return sheet('Cancelar actividad',`<p>¿Querés cancelar «${esc(r.title)}»? Su historial se conservará.</p><div class="actions">${button('Volver','event',r.id,'btn quiet')}${button('Confirmar cancelación','cancel-event',r.id,'btn danger')}</div>`)}
if(s.type==='reset')return sheet('Restablecer la demo',`<p>Se borrarán los cambios de esta demostración en este navegador y volverá la familia de ejemplo.</p><div class="actions">${button('Conservar cambios','close','','btn quiet')}${button('Restablecer','confirm-reset','','btn danger')}</div>`);
}
function denied(){sheet('Información no disponible',`<p>No tenés acceso a este contenido con el perfil actual.</p>${button('Volver','close','','btn full')}`)}
function saved(msg){persist();close();render();toast(msg)}
function accessibleEvent(e){return can(e,'care')}
const actions={
close:()=>close(),switch:()=>open('switch'),actor:p=>{if(!actors.includes(p))return;user=p;localStorage.setItem('nido-actor-v3',user);filter='all';docQuery='';chat=[];tab='calendar';selected=today();close();render();toast(`Ahora estás viendo como ${people[p].name}`)},
tab:t=>{tab=t;filter='all';docQuery='';close();render()},filter:p=>{filter=p;render()},'cal-section':v=>{calSection=v;render()},'cal-mode':()=>{calMode=calMode==='week'?'month':'week';render()},day:d=>{selected=d;render()},today:()=>{selected=today();render()},shift:n=>{if(calMode==='week')selected=addDay(selected,Number(n)*7);else{const d=new Date(selected+'T12:00');d.setDate(1);d.setMonth(d.getMonth()+Number(n));selected=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`}render()},
'new-event':()=>allowedPatients('care').length?open('event-form'):toast('No tenés un integrante disponible para crear actividades.'),'edit-event':id=>open('event-form',id),event:id=>open('event',id),
complete:id=>{let e=db.events.find(e=>e.id===id);if(!accessibleEvent(e))return denied();e.status='done';log(e,'Marcó como realizada');render();toast('Actividad registrada')},reopen:id=>{let e=db.events.find(e=>e.id===id);if(!accessibleEvent(e))return denied();e.status='pending';log(e,'Reabrió el pendiente');render()},'confirm-cancel':id=>open('cancel',id),'cancel-event':id=>{let e=db.events.find(e=>e.id===id);if(!accessibleEvent(e))return denied();e.status='canceled';log(e,'Canceló la actividad');saved('Actividad cancelada; se conserva su registro')},question:id=>open('question',id),
document:id=>open('document',id),upload:()=>open('upload'),example:()=>{const owner=$('#upload-form select')?.value||allowedPatients()[0];open('review','',{owner,example:true})},'finish-upload':()=>{tab='docs';filter='all';saved('Documento guardado')},'doc-task':id=>open('doc-task',id),'doc-privacy':id=>open('privacy',id),
'new-med':()=>open('med-form'),med:id=>open('med',id),batch:arg=>{const [id,batch]=arg.split(':');open('batch',id,{batch})},purchase:id=>open('purchase',id),shopping:id=>{let m=db.meds.find(m=>m.id===id);if(!can(m))return denied();m.shopping=!m.shopping;log(m,m.shopping?'Agregó a reposición':'Quitó de reposición');render()},renew:id=>{let m=db.meds.find(m=>m.id===id);if(!can(m))return denied();if(!db.events.some(e=>e.medSource===id&&e.status==='pending'))db.events.push({id:window.crypto.randomUUID(),owner:m.owner,medSource:id,title:`Renovar receta de ${m.title}`,date:'',time:'',type:'Trámite',assignee:user,visibility:m.visibility,status:'pending',notes:'Coordinar la renovación con el prestador.',history:[]});tab='calendar';calSection='tasks';saved('Gestión de receta agregada a pendientes')},
person:id=>open('person',id),'person-docs':p=>{tab='docs';filter=p;close();render()},notes:p=>open('notes',p),vaccines:p=>open('vaccines',p),permissions:p=>open('permissions',p),
revoke:who=>{if(sheetState?.id!==user)return;delete db.grants[user][who];db.audit.push({owner:user,by:user,at:stamp(),action:`Revocó el acceso de ${people[who].name}`});persist();render();toast('Acceso revocado')},grant:who=>{if(sheetState?.id!==user)return;db.grants[user][who]=who==='rosa'?'care':'manage';db.audit.push({owner:user,by:user,at:stamp(),action:`Autorizó a ${people[who].name}`});db.requests.filter(r=>r.owner===user&&r.by===who).forEach(r=>r.status='accepted');persist();render()},request:owner=>{if(user!=='sofia'||db.requests.some(r=>r.owner===owner&&r.status==='pending'))return toast('La solicitud está pendiente');db.requests.push({id:id(),owner,by:user,status:'pending'});persist();render();toast('Solicitud registrada. Antonio puede aceptarla en su perfil.')},approve:rid=>{const r=db.requests.find(r=>r.id===rid);if(r?.owner!==user)return;actions.grant(r.by)},alerts:()=>open('alerts'),ask:q=>ask(q),reset:()=>open('reset'),'confirm-reset':()=>{db=seed();user='sofia';localStorage.setItem('nido-actor-v3',user);chat=[];tab='calendar';filter='all';saved('Datos de ejemplo restablecidos')}
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){const action=actions[b.dataset.action];if(action)action(b.dataset.id)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,f=new FormData(form),v=Object.fromEntries(f.entries()),s=sheetState;
if(form.id==='search-form'){docQuery=v.query;return render()}
if(form.id==='chat-form'){if(v.query.trim())ask(v.query.trim());return}
if(form.id==='event-form'){let prior=s.id?db.events.find(e=>e.id===s.id):null;if(prior&&!can(prior,'care')||!canOwner(v.owner,'care'))return denied();if(!v.title.trim())return;const r={...(prior||{id:id(),status:'pending',history:[]}),owner:prior?.source?prior.owner:v.owner,title:v.title.trim(),date:v.date,time:v.time,type:v.type,scope:user==='rosa'?'care':v.type==='Cuidado'?'care':'clinical',assignee:v.assignee,location:v.location,notes:v.notes,reminder:v.reminder,recipient:v.recipient,visibility:v.owner===user&&v.private?'private':prior?.visibility==='private'&&prior.owner!==user?'private':'shared'};if(prior)db.events[db.events.indexOf(prior)]=r;else db.events.push(r);log(r,prior?'Editó la actividad':'Creó la actividad');selected=r.date||today();saved('Actividad guardada');return}
if(form.id==='upload-form'){const file=f.get('file');if(!file||!file.size)return toast('Elegí un archivo o usá el ejemplo preparado.');if(file.size>1024*1024)return toast('El archivo supera 1 MB. Usá uno más pequeño para la demo.');if(!/^image\//.test(file.type)&&file.type!=='application/pdf')return toast('Elegí una imagen o un PDF.');const attachment=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});open('review','',{owner:v.owner,attachment,filename:file.name,example:false});return}
if(form.id==='review-form'){if(!canOwner(v.owner))return denied();const r={id:id(),owner:v.owner,title:v.title.trim(),date:v.date,text:v.text.trim(),kind:'Documento',visibility:v.private?'private':'shared',by:user,attachment:s.attachment||null,filename:s.filename||null};db.documents.push(r);if(!persist()){db.documents.pop();return}open('doc-saved',r.id);return}
if(form.id==='doc-task-form'){const d=db.documents.find(d=>d.id===s.id);if(!can(d))return denied();db.events.push({id:id(),owner:d.owner,title:v.title.trim(),date:v.date,time:'',type:'Pendiente',assignee:v.assignee,source:d.id,visibility:d.visibility,status:'pending',notes:'Creado a partir de un documento. Revisar la fuente antes de gestionar.',history:[{by:user,at:stamp(),action:'Creó pendiente desde documento'}]});tab='calendar';calSection='tasks';saved('Pendiente creado y vinculado a su fuente');return}
if(form.id==='med-form'){if(!canOwner(v.owner))return denied();db.meds.push({id:id(),owner:v.owner,title:v.title.trim(),unit:v.unit,rx:v.rx,visibility:'shared',updated:today(),shopping:false,batches:[{id:id(),qty:Number(v.qty),expiry:v.expiry}],history:[{by:user,at:stamp(),action:'Registró medicamento'}]});saved('Medicamento registrado');return}
if(form.id==='stock-form'){const m=db.meds.find(m=>m.id===s.id);if(!can(m))return denied();const n=Number(v.qty);if(!Number.isInteger(n)||n<0)return toast('Ingresá una cantidad válida.');if(s.type==='purchase'){m.batches.push({id:id(),qty:n,expiry:v.expiry});m.shopping=false}else{const b=m.batches.find(b=>b.id===s.batch);b.qty=n;b.expiry=v.expiry}m.updated=today();log(m,s.type==='purchase'?'Registró compra':'Corrigió existencias');open('med',m.id);render();return}
if(form.id==='privacy-form'){const d=db.documents.find(d=>d.id===s.id);if(d?.owner!==user)return denied();d.visibility=v.visibility;db.events.filter(e=>e.source===d.id).forEach(e=>e.visibility=v.visibility);db.audit.push({owner:user,by:user,at:stamp(),action:`Cambió visibilidad de ${d.title} a ${v.visibility==='private'?'Solo yo':'Compartido'}`});persist();open('document',d.id);render();return}
if(form.id==='note-form'){if(!canOwner(s.id,'care'))return denied();db.notes.push({id:id(),owner:s.id,by:user,scope:'care',visibility:'shared',date:today(),text:v.text.trim()});persist();render();toast('Observación guardada');return}
if(form.id==='vaccine-form'){if(!canOwner(s.id))return denied();db.vaccines.push({id:id(),owner:s.id,title:v.title.trim(),date:v.date,visibility:'shared',text:'Registro ingresado manualmente en la demo.'});persist();render();return}
if(form.id==='question-form'){const r=db.events.find(e=>e.id===s.id);if(!can(r,'care'))return denied();r.questions??=[];r.questions.push(v.text.trim());log(r,'Agregó pregunta para la consulta');open('event',r.id);render();return}
});
render();
if(!localStorage.getItem('nido-actor-v3'))open('switch');
